WITH lines AS (SELECT id, li_item.product_id, li_item.qty, li_item.price, li_item.promo FROM carts LATERAL VIEW EXPLODE(items) t AS li_item) SELECT *, CUME_DIST() OVER (PARTITION BY promo ORDER BY product_id DESC) product_id_cume_dist, COUNT(product_id) OVER (PARTITION BY promo) promo_count_product_id, PERCENT_RANK() OVER (PARTITION BY promo ORDER BY product_id DESC NULLS LAST) product_id_percent_rank, ROUND(product_id / SUM(product_id) OVER (PARTITION BY promo), 4) product_id_share FROM lines
